css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .serie-cajas{display: flex; gap: 6px; flex-wrap: nowrap; font-size: 17px; font-weight: 700;}
.mz .serie-cajas .caja-num{width: 54px; height: 46px; border: 1.5px solid var(--bosque); border-radius: 6px; display: flex; align-items: center; justify-content: center; flex-shrink: 0;}
.mz .serie-cajas .caja-num.vacia{background: #fff;}
.mz .cuenta-fila{display: grid; grid-template-columns: 1fr 90px; gap: 10px; padding: 8px 10px; border: 1.2px solid var(--bosque); border-radius: 6px; margin-bottom: 6px; align-items: center;}
.mz .cuenta-dibujos{font-size: 17px; font-weight: 600; letter-spacing: 1px;}
.mz .cuenta-caja{border: 1.5px solid var(--bosque); border-radius: 6px; height: 38px;}
